// ============================================================================
// FreeLang Stats Cache 모듈 - 통계 캐싱 (Phase 12)
// ============================================================================
// 목표: stats_build(t) O(n) 반복 호출 제거
// 원리: row_count 기반으로 통계 유효성 판단, 불변 시 O(1) 반환
// ============================================================================

module stats_cache {
    const CACHE_OK:      i32 = 0;
    const CACHE_MISS:    i32 = 1;
    const CACHE_HIT:     i32 = 2;

    const MAX_COLS: i32 = 16;

    // === 캐시 상태 저장 구조체 ===
    struct StatsCache {
        cached_stats:       planner.TableStats;   // 마지막 빌드된 통계
        row_count_snapshot: i32;                  // 빌드 시점의 row_count
        is_valid:           bool;                 // 캐시 유효 여부
        hit_count:          i32;                  // 캐시 히트 횟수 (벤치마크용)
        miss_count:         i32;                  // 캐시 미스 횟수
    }

    // === 캐시 초기화 ===
    // 새 캐시를 무효 상태로 생성
    func stats_cache_new() -> StatsCache {
        let sc = StatsCache{
            cached_stats: planner.TableStats{
                row_count:    0,
                col_count:    0,
                col_min:      make([i64], MAX_COLS),
                col_max:      make([i64], MAX_COLS),
                col_null_cnt: make([i32], MAX_COLS),
                col_type:     make([i32], MAX_COLS),
            },
            row_count_snapshot: 0,
            is_valid:           false,
            hit_count:          0,
            miss_count:         0,
        };
        return sc;
    }

    // === 캐시 조회 (핵심 함수) ===
    // row_count가 같으면 캐시 반환 (O(1))
    // 다르면 stats_build 후 캐시 갱신 (O(n))
    func stats_cache_get(sc: *StatsCache, t: schema.Table) -> planner.TableStats {
        // 캐시 유효성 확인: 이전 row_count와 현재 row_count 비교
        if sc.is_valid && t.row_count == sc.row_count_snapshot {
            // 캐시 히트 (O(1))
            sc.hit_count = sc.hit_count + 1;
            return sc.cached_stats;
        }

        // 캐시 미스 (O(n) - stats_build)
        sc.miss_count = sc.miss_count + 1;
        sc.cached_stats = planner.stats_build(t);
        sc.row_count_snapshot = t.row_count;
        sc.is_valid = true;

        return sc.cached_stats;
    }

    // === 캐시 무효화 ===
    // INSERT/UPDATE/DELETE 후 호출하여 강제 재계산 유발
    func stats_cache_invalidate(sc: *StatsCache) {
        sc.is_valid = false;
        sc.hit_count = 0;
        sc.miss_count = 0;
    }

    // === 캐시 통계 출력 ===
    // 캐시 성능을 모니터링하는 디버그 함수
    func stats_cache_stats(sc: *StatsCache) -> string {
        let result = "";

        // 캐시 상태
        result = result + "[StatsCache] ";

        if !sc.is_valid {
            result = result + "INVALID";
        } else {
            result = result + "VALID";
        }

        result = result + " | row_count=" + i32_to_string(sc.row_count_snapshot);
        result = result + " | hit=" + i32_to_string(sc.hit_count);
        result = result + " | miss=" + i32_to_string(sc.miss_count);

        // 히트율 계산
        let total = sc.hit_count + sc.miss_count;
        if total > 0 {
            // 백분율 계산 (정수 기반): (hit * 100) / total
            let hit_pct = (sc.hit_count * 100) / total;
            result = result + " | hit_rate=" + i32_to_string(hit_pct) + "%";
        }

        return result;
    }

    // === 헬퍼 함수: i32 → string 변환 ===
    // (플래너와 다른 모듈에서도 사용하므로 로컬 구현)
    func i32_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }

        // 음수 처리
        let negative = false;
        let num = n;
        if num < 0 {
            negative = true;
            num = 0 - num;
        }

        // 자릿수 계산 및 역순 빌드
        let digits = make([i32], 16);
        let digit_count = 0;
        let temp = num;

        for temp > 0 {
            let digit = temp % 10;
            digits[digit_count] = digit;
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        // 역순 -> 정순 문자열 생성
        let result = "";
        if negative {
            result = "-";
        }

        let idx = digit_count - 1;
        for idx >= 0 {
            let ch_code = 48 + digits[idx];  // '0' = 48
            result = result + chr(ch_code);
            idx = idx - 1;
        }

        return result;
    }
}

