// 목표: schema.fl + query.fl의 풀 스캔 병목 해결 (O(n) → O(log n))
// 원리:
//   1. 노드 풀: 배열 기반 노드 저장 (포인터 대신 인덱스)
//   2. 트리 탐색: while 루프로 루트부터 리프까지 (재귀 없음)
//   3. 범위 스캔: 리프 노드 연결 리스트 순회
//   4. 삽입/삭제: 노드 분할/합병으로 균형 유지
// 구조:
//   - 상수 정의 (차수, 제한값)
//   - BTreeNode, BTreeIndex 구조체
//   - 탐색 함수 (find_leaf, binary_search)
//   - 삽입/삭제 함수
//   - 범위 스캔 함수
// ============================================================================

module index {
    // === 상수: B+Tree 설정 ===
    const ORDER:       i32 = 4;    // 차수 (최대 2*ORDER 키)
    const MAX_KEYS:    i32 = 8;    // 노드당 최대 키
    const MAX_PTRS:    i32 = 9;    // 노드당 최대 포인터 (자식)
    const MAX_NODES:   i32 = 512;  // 전체 노드 풀 크기

    // === 상수: 에러 코드 ===
    const IDX_OK:         i32 = 0;
    const IDX_ERR_FULL:   i32 = 50;
    const IDX_ERR_DUP:    i32 = 51;
    const IDX_ERR_NOTFOUND: i32 = 52;

    // === 데이터 구조체 ===

    struct BTreeNode {
        is_leaf:    bool;
        key_count:  i32;
        keys:       [i64];      // 정렬된 키 배열
        row_ids:    [i64];      // 리프 노드: 각 키의 row_id
        children:   [i32];      // 내부 노드: 자식 인덱스
        parent:     i32;        // 부모 인덱스 (-1 = 루트)
        next_leaf:  i32;        // 다음 리프 노드 (-1 = 마지막)
        prev_leaf:  i32;        // 이전 리프 노드 (-1 = 처음)
    }

    struct BTreeIndex {
        col_idx:    i32;
        root:       i32;        // 루트 노드 인덱스
        nodes:      [BTreeNode];
        node_count: i32;
        height:     i32;
        key_count:  i64;
    }

    // === 팩토리 함수 ===

    func index_new(col_idx: i32) -> BTreeIndex {
        let root_node = BTreeNode{
            is_leaf:    true,
            key_count:  0,
            keys:       make([i64], MAX_KEYS),
            row_ids:    make([i64], MAX_KEYS),
            children:   make([i32], MAX_PTRS),
            parent:     -1,
            next_leaf:  -1,
            prev_leaf:  -1,
        };
        let nodes = make([BTreeNode], MAX_NODES);
        nodes[0] = root_node;
        return BTreeIndex{
            col_idx:    col_idx,
            root:       0,
            nodes:      nodes,
            node_count: 1,
            height:     1,
            key_count:  0,
        };
    }

    // === 핵심 탐색 함수 ===

    // 키가 속할 리프 노드 찾기
    func (idx: *BTreeIndex) find_leaf(key: i64) -> i32 {
        let current = idx.root;
        let i = 0;
        for i = 0; i < 100; i = i + 1 {  // 최대 높이 100 제한
            let node = idx.nodes[current];
            if node.is_leaf {
                return current;
            }
