// ============================================================================
// FreeLang Index Manager 모듈 - 인덱스 자동 빌드/관리 (Phase 12)
// ============================================================================
// 목표: 컬럼별 INT/STR 인덱스를 일원화하여 관리
// 원리: IndexManager는 컬럼별 인덱스 슬롯을 유지하고, 동적으로 빌드/조회
// ============================================================================

module index_manager {
    // === 에러 코드 ===
    const IDX_MGR_OK:         i32 = 0;
    const IDX_MGR_ERR_FULL:   i32 = 200;
    const IDX_MGR_ERR_NOTFOUND: i32 = 201;
    const IDX_MGR_ERR_TYPE:   i32 = 202;

    const MAX_IDX_COLS: i32 = 16;  // schema.MAX_COLS와 동일

    // === 인덱스 매니저 구조체 ===
    struct IndexManager {
        // INT 인덱스 레지스트리
        int_indices:    [index.BTreeIndex];   // [MAX_IDX_COLS]
        int_idx_active: [bool];
        int_idx_count:  i32;

        // STR 인덱스 레지스트리
        str_indices:    [index_str.StrIndex]; // [MAX_IDX_COLS]
        str_idx_active: [bool];
        str_idx_count:  i32;
    }

    // === 초기화 ===

    func index_manager_new() -> IndexManager {
        let im = IndexManager{
            int_indices:    make([index.BTreeIndex], MAX_IDX_COLS),
            int_idx_active: make([bool], MAX_IDX_COLS),
            int_idx_count:  0,
            str_indices:    make([index_str.StrIndex], MAX_IDX_COLS),
            str_idx_active: make([bool], MAX_IDX_COLS),
            str_idx_count:  0,
        };

        // 모든 슬롯을 비활성으로 초기화
        let idx = 0;
        for idx = 0; idx < MAX_IDX_COLS; idx = idx + 1 {
            im.int_idx_active[idx] = false;
            im.str_idx_active[idx] = false;
        }

        return im;
    }

    // === INT 인덱스 빌드 ===
    // 테이블의 INT 컬럼을 BTreeIndex로 인덱싱
    // 성공 시 IDX_MGR_OK, 실패 시 에러 코드 반환
    func index_manager_build_int(im: *IndexManager, t: schema.Table, col_idx: i32) -> i32 {
        // 검증
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return IDX_MGR_ERR_NOTFOUND;
        }

        if col_idx >= t.schema.col_count {
            return IDX_MGR_ERR_NOTFOUND;
        }

        if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_INT {
            return IDX_MGR_ERR_TYPE;
        }

        // 이미 활성화되어 있으면 재구축
        if im.int_idx_active[col_idx] {
            // 기존 인덱스 대체 (재초기화)
            im.int_indices[col_idx] = index.index_new(col_idx);
        } else {
            // 새 인덱스 생성
            im.int_indices[col_idx] = index.index_new(col_idx);
            im.int_idx_active[col_idx] = true;
            im.int_idx_count = im.int_idx_count + 1;
        }

        // 테이블의 모든 행을 인덱스에 삽입
        let row_idx = 0;
        for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
            // 삭제된 행 스킵
            if t.deleted_flags[row_idx] {
                continue;
            }

            // SoA 레이아웃: [col_idx * MAX_ROWS + row_idx]
            let soa_idx = col_idx * schema.MAX_ROWS + row_idx;
            let key = t.int_cols[soa_idx];
            let row_id = t.row_ids[row_idx];

            // 인덱스 삽입 시도
            let result = im.int_indices[col_idx].index_insert(key, row_id);

            // MAX_KEYS 초과 시 (노드 분할 미구현) 폴백
            if result == index.IDX_ERR_FULL {
                // 인덱스 빌드 실패 → 활성화 해제 (FULL_SCAN으로 폴백)
                im.int_idx_active[col_idx] = false;
                im.int_idx_count = im.int_idx_count - 1;
                return IDX_MGR_ERR_FULL;
            }
        }

        return IDX_MGR_OK;
    }

    // === STR 인덱스 빌드 ===
    // 테이블의 STR 컬럼을 StrIndex로 인덱싱
    func index_manager_build_str(im: *IndexManager, t: schema.Table, col_idx: i32) -> i32 {
        // 검증
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return IDX_MGR_ERR_NOTFOUND;
        }

        if col_idx >= t.schema.col_count {
            return IDX_MGR_ERR_NOTFOUND;
        }

        if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_STR {
            return IDX_MGR_ERR_TYPE;
        }

        // 이미 활성화되어 있으면 재구축
        if im.str_idx_active[col_idx] {
            im.str_indices[col_idx] = index_str.str_index_new(col_idx);
        } else {
            im.str_indices[col_idx] = index_str.str_index_new(col_idx);
            im.str_idx_active[col_idx] = true;
            im.str_idx_count = im.str_idx_count + 1;
        }

        // 테이블의 모든 행을 인덱스에 삽입
        let row_idx = 0;
        for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
            // 삭제된 행 스킵
            if t.deleted_flags[row_idx] {
                continue;
            }

            // SoA 레이아웃: [col_idx * MAX_ROWS + row_idx]
            let soa_idx = col_idx * schema.MAX_ROWS + row_idx;
            let key = t.str_cols[soa_idx];
            let row_id = t.row_ids[row_idx];

            // 인덱스 삽입 시도
            let result = im.str_indices[col_idx].str_insert(key, row_id);

            // FULL 시 폴백
            if result == index_str.STR_IDX_ERR_FULL {
                im.str_idx_active[col_idx] = false;
                im.str_idx_count = im.str_idx_count - 1;
                return IDX_MGR_ERR_FULL;
            }
        }

        return IDX_MGR_OK;
    }

    // === INT 인덱스 유무 확인 ===
    func index_manager_has_int(im: *IndexManager, col_idx: i32) -> bool {
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return false;
        }
        return im.int_idx_active[col_idx];
    }

    // === STR 인덱스 유무 확인 ===
    func index_manager_has_str(im: *IndexManager, col_idx: i32) -> bool {
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return false;
        }
        return im.str_idx_active[col_idx];
    }

    // === INT 인덱스 조회 ===
    // 인덱스가 없으면 빈 BTreeIndex 반환
    func index_manager_get_int(im: *IndexManager, col_idx: i32) -> index.BTreeIndex {
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return index.index_new(-1);  // 빈 인덱스
        }
        if !im.int_idx_active[col_idx] {
            return index.index_new(-1);
        }
        return im.int_indices[col_idx];
    }

    // === STR 인덱스 조회 ===
    // 인덱스가 없으면 빈 StrIndex 반환
    func index_manager_get_str(im: *IndexManager, col_idx: i32) -> index_str.StrIndex {
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return index_str.str_index_new(-1);  // 빈 인덱스
        }
        if !im.str_idx_active[col_idx] {
            return index_str.str_index_new(-1);
        }
        return im.str_indices[col_idx];
    }

    // === 디버그 통계 ===
    func index_manager_stats(im: *IndexManager) -> string {
        let result = "[IndexManager] ";
        result = result + "int_active=" + i32_to_string(im.int_idx_count) + "/" + i32_to_string(MAX_IDX_COLS);
        result = result + " | str_active=" + i32_to_string(im.str_idx_count) + "/" + i32_to_string(MAX_IDX_COLS);
        return result;
    }

    // === 헬퍼 함수: i32 → string ===
    func i32_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }

        let negative = false;
        let num = n;
        if num < 0 {
            negative = true;
            num = 0 - num;
        }

        let digits = make([i32], 16);
        let digit_count = 0;
        let temp = num;

        for temp > 0 {
            let digit = temp % 10;
            digits[digit_count] = digit;
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        let result = "";
        if negative {
            result = "-";
        }

        let idx = digit_count - 1;
        for idx >= 0 {
            let ch_code = 48 + digits[idx];
            result = result + chr(ch_code);
            idx = idx - 1;
        }

        return result;
    }
}

