    // 인덱스가 없으면 빈 BTreeIndex 반환
    func index_manager_get_int(im: *IndexManager, col_idx: i32) -> index.BTreeIndex {
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return index.index_new(-1);  // 빈 인덱스
        }
        if !im.int_idx_active[col_idx] {
            return index.index_new(-1);
        }
        return im.int_indices[col_idx];
    }

    // === STR 인덱스 조회 ===
    // 인덱스가 없으면 빈 StrIndex 반환
    func index_manager_get_str(im: *IndexManager, col_idx: i32) -> index_str.StrIndex {
        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
            return index_str.str_index_new(-1);  // 빈 인덱스
        }
        if !im.str_idx_active[col_idx] {
            return index_str.str_index_new(-1);
        }
        return im.str_indices[col_idx];
    }

    // === 디버그 통계 ===
    func index_manager_stats(im: *IndexManager) -> string {
        let result = "[IndexManager] ";
        result = result + "int_active=" + i32_to_string(im.int_idx_count) + "/" + i32_to_string(MAX_IDX_COLS);
        result = result + " | str_active=" + i32_to_string(im.str_idx_count) + "/" + i32_to_string(MAX_IDX_COLS);
        return result;
    }

    // === 헬퍼 함수: i32 → string ===
    func i32_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
