        let negative = false;
        let num = n;
        if num < 0 {
            negative = true;
            num = 0 - num;
        }

        let digits = make([i32], 16);
        let digit_count = 0;
        let temp = num;

        for temp > 0 {
            let digit = temp % 10;
            digits[digit_count] = digit;
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        let result = "";
        if negative {
            result = "-";
        }

        let idx = digit_count - 1;
        for idx >= 0 {
            let ch_code = 48 + digits[idx];
            result = result + chr(ch_code);
            idx = idx - 1;
        }

        return result;
    }
}

