//   - 쿼리 빌더 함수 (체이닝 스타일)
//   - query_execute 실행 엔진
// ============================================================================

module query {
    // === 비교 연산자 ===
    const OP_EQ:   i32 = 1;   // ==
    const OP_NE:   i32 = 2;   // !=
    const OP_GT:   i32 = 3;   // >
    const OP_LT:   i32 = 4;   // <
    const OP_GE:   i32 = 5;   // >=
    const OP_LE:   i32 = 6;   // <=
    const OP_LIKE: i32 = 7;   // 접두어 일치 (str_starts_with)

