    const AGG_NONE:  i32 = 0;
    const AGG_COUNT: i32 = 1;
    const AGG_SUM:   i32 = 2;
    const AGG_MAX:   i32 = 3;
    const AGG_MIN:   i32 = 4;

    // === 제한값 ===
    const MAX_WHERE: i32 = 8;
    const MAX_RESULT_ROWS: i32 = 1024;

    // === 에러 코드 ===
