        order_by:    OrderBy;
        has_order:   bool;
        limit:       i32;
        offset:      i32;
        agg_type:    i32;
        agg_col:     i32;
    }

    struct QueryResult {
        // 결과 행 인덱스 (schema.Table의 row_idx)
        row_indices: [i32];
        row_count:   i32;
        agg_value:   i64;
        error_code:  i32;
    }

    // === 쿼리 실행 (핵심) ===
    // schema.Table을 직접 받아서 처리

