// ============================================================================
// FreeLang Query Optimizer 모듈 - 통합 옵티마이져 (Phase 12)
// ============================================================================
// 목표: StatsCache + IndexManager를 통합하여 query_runner.fl에 파사드 제공
// 핵심: plan_query의 has_int_idx/has_str_idx 플래그를 동적으로 결정
// ============================================================================

module query_optimizer {
    // === 에러 코드 ===
    const OPT_OK:             i32 = 0;
    const OPT_ERR_NOT_READY:  i32 = 210;
    const OPT_ERR_INDEX:      i32 = 211;

    // === 옵티마이저 컨텍스트 ===
    struct OptimizerContext {
        stats_cache:  stats_cache.StatsCache;
        idx_manager:  index_manager.IndexManager;
        is_ready:     bool;
        query_count:  i32;        // 실행된 쿼리 수 (벤치마크용)
    }

    // === 초기화 ===
    func optimizer_new() -> OptimizerContext {
        let ctx = OptimizerContext{
            stats_cache: stats_cache.stats_cache_new(),
            idx_manager: index_manager.index_manager_new(),
            is_ready:    true,
            query_count: 0,
        };
        return ctx;
    }

    // === 인덱스 빌드 ===
    // 사용자가 특정 컬럼에 인덱스를 명시적으로 빌드하도록 요청
    func optimizer_build_index(ctx: *OptimizerContext, t: schema.Table, col_idx: i32) -> i32 {
        if !ctx.is_ready {
            return OPT_ERR_NOT_READY;
        }

        if col_idx < 0 || col_idx >= t.schema.col_count {
            return OPT_ERR_INDEX;
        }

        let col_type = t.schema.col_defs[col_idx].col_type;

        // INT 컬럼
        if col_type == schema.COL_TYPE_INT {
            let result = index_manager.index_manager_build_int(&ctx.idx_manager, t, col_idx);
            return result;
        }

        // STR 컬럼
        if col_type == schema.COL_TYPE_STR {
            let result = index_manager.index_manager_build_str(&ctx.idx_manager, t, col_idx);
            return result;
        }

        // BOOL 컬럼은 인덱스 미지원
        return OPT_ERR_INDEX;
    }

    // === 통합 실행 계획 생성 (핵심 함수) ===
    // 병목 1 + 2 동시 해결:
    //   - 병목 1: IndexManager로 has_int_idx/has_str_idx 동적 결정
    //   - 병목 2: StatsCache로 row_count 기반 통계 캐싱
    func optimizer_plan(ctx: *OptimizerContext, t: schema.Table, q: query.Query) -> planner.ExecPlan {
        if !ctx.is_ready {
            let ep = planner.ExecPlan{
                plan_type:  planner.PLAN_FULL_SCAN,
                index_col:  -1,
                est_rows:   t.row_count,
                cost:       t.row_count,
                error_code: OPT_ERR_NOT_READY,
            };
            return ep;
        }

        // === 1단계: 통계 조회 (캐시 활용, 병목 2 해결) ===
        let stats = stats_cache.stats_cache_get(&ctx.stats_cache, t);

        // === 2단계: 인덱스 유무 판단 (병목 1 해결) ===
        let has_int_idx = false;
        let has_str_idx = false;

        // WHERE 절이 있는 첫 번째 조건을 인덱스로 최적화 시도
        if q.where_count >= 1 {
            let where_col = q.wheres[0].col_idx;
            let where_op = q.wheres[0].op;

            // INT 컬럼 인덱스
            if !q.wheres[0].is_str {
                if index_manager.index_manager_has_int(&ctx.idx_manager, where_col) {
                    has_int_idx = true;
                }
            }
            // STR 컬럼 인덱스
            else {
                if index_manager.index_manager_has_str(&ctx.idx_manager, where_col) {
                    has_str_idx = true;
                }
            }
        }

        // === 3단계: 플래너에 정확한 플래그 전달 ===
        // 기존 query_runner.fl의 plan_query(q, stats, false, false)를 대체
        let exec_plan = planner.plan_query(q, stats, has_int_idx, has_str_idx);

        ctx.query_count = ctx.query_count + 1;
        return exec_plan;
    }

    // === 인덱스 직접 조회 (executor/physical_plan 연동용) ===
    func optimizer_get_int_index(ctx: *OptimizerContext, col_idx: i32) -> index.BTreeIndex {
        return index_manager.index_manager_get_int(&ctx.idx_manager, col_idx);
    }

    func optimizer_get_str_index(ctx: *OptimizerContext, col_idx: i32) -> index_str.StrIndex {
        return index_manager.index_manager_get_str(&ctx.idx_manager, col_idx);
    }

    // === 통계 캐시 상태 조회 ===
    func optimizer_stats_cache(ctx: *OptimizerContext) -> string {
        return stats_cache.stats_cache_stats(&ctx.stats_cache);
    }

    // === 인덱스 매니저 상태 조회 ===
    func optimizer_stats_manager(ctx: *OptimizerContext) -> string {
        return index_manager.index_manager_stats(&ctx.idx_manager);
    }

    // === 통합 통계 출력 ===
    func optimizer_stats(ctx: *OptimizerContext) -> string {
        let result = "";
        result = result + optimizer_stats_cache(ctx);
        result = result + " | ";
        result = result + optimizer_stats_manager(ctx);
        result = result + " | query_count=" + i32_to_string(ctx.query_count);
        return result;
    }

    // === 헬퍼: i32 → string ===
    func i32_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }

        let negative = false;
        let num = n;
        if num < 0 {
            negative = true;
            num = 0 - num;
        }

        let digits = make([i32], 16);
        let digit_count = 0;
        let temp = num;

        for temp > 0 {
            let digit = temp % 10;
            digits[digit_count] = digit;
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        let result = "";
        if negative {
            result = "-";
        }

        let idx = digit_count - 1;
        for idx >= 0 {
            let ch_code = 48 + digits[idx];
            result = result + chr(ch_code);
            idx = idx - 1;
        }

        return result;
    }
}

