                if index_manager.index_manager_has_str(&ctx.idx_manager, where_col) {
                    has_str_idx = true;
                }
            }
        }

        // === 3단계: 플래너에 정확한 플래그 전달 ===
        // 기존 query_runner.fl의 plan_query(q, stats, false, false)를 대체
        let exec_plan = planner.plan_query(q, stats, has_int_idx, has_str_idx);

        ctx.query_count = ctx.query_count + 1;
        return exec_plan;
    }

    // === 인덱스 직접 조회 (executor/physical_plan 연동용) ===
    func optimizer_get_int_index(ctx: *OptimizerContext, col_idx: i32) -> index.BTreeIndex {
        return index_manager.index_manager_get_int(&ctx.idx_manager, col_idx);
    }

    func optimizer_get_str_index(ctx: *OptimizerContext, col_idx: i32) -> index_str.StrIndex {
        return index_manager.index_manager_get_str(&ctx.idx_manager, col_idx);
    }

    // === 통계 캐시 상태 조회 ===
    func optimizer_stats_cache(ctx: *OptimizerContext) -> string {
        return stats_cache.stats_cache_stats(&ctx.stats_cache);
    }

    // === 인덱스 매니저 상태 조회 ===
    func optimizer_stats_manager(ctx: *OptimizerContext) -> string {
        return index_manager.index_manager_stats(&ctx.idx_manager);
    }

    // === 통합 통계 출력 ===
    func optimizer_stats(ctx: *OptimizerContext) -> string {
        let result = "";
        result = result + optimizer_stats_cache(ctx);
        result = result + " | ";
        result = result + optimizer_stats_manager(ctx);
        result = result + " | query_count=" + i32_to_string(ctx.query_count);
        return result;
    }

    // === 헬퍼: i32 → string ===
    func i32_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }

        let negative = false;
        let num = n;
        if num < 0 {
            negative = true;
            num = 0 - num;
        }

        let digits = make([i32], 16);
        let digit_count = 0;
        let temp = num;

        for temp > 0 {
            let digit = temp % 10;
            digits[digit_count] = digit;
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        let result = "";
        if negative {
            result = "-";
        }

        let idx = digit_count - 1;
        for idx >= 0 {
            let ch_code = 48 + digits[idx];
            result = result + chr(ch_code);
            idx = idx - 1;
        }

        return result;
    }
}

