            limit_count:   -1,
            has_error:     false,
            error_code:    0,
        };

        qr.exec_plan = planner.ExecPlan{
            plan_type:  0,
            index_col:  -1,
            est_rows:   0,
            cost:       0,
            error_code: 0,
        };

        qr.phys_plan = physical_plan.physical_plan_new();
        qr.ex = executor.executor_new();
        qr.result = result_set.result_set_new(16);

        qr.stats = PipelineStats{
            parse_ok:    false,
            plan_type:   0,
            op_count:    0,
            result_rows: 0,
            error_code:  0,
        };

        qr.has_error = false;
        qr.error_code = QR_OK;

        return QR_OK;
    }

    // === 디버그 함수 ===

    // QueryRunner 상태 문자열 표현
    func query_runner_stats(qr: *QueryRunner) -> string {
        let result = "QueryRunner {parse_ok: ";

        if qr.stats.parse_ok {
            result = result + "true";
        } else {
            result = result + "false";
        }

        result = result + ", plan_type: ";
        result = result + int_to_string(qr.stats.plan_type);

        result = result + ", op_count: ";
        result = result + int_to_string(qr.stats.op_count);

        result = result + ", result_rows: ";
        result = result + int_to_string(qr.stats.result_rows);

        result = result + ", error: ";
        result = result + int_to_string(qr.stats.error_code);

        result = result + "}";

        return result;
    }

    // === 헬퍼 함수 ===

    // 정수를 문자열로 변환
    @inline
    func int_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }
        if n < 0 {
            return "-" + int_to_string(-n);
        }

        let digits = "";
        let temp = n;
        let digit_count = 0;
        let pow10 = 1;

        // 자리수 계산
        while temp > 0 {
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        // 10의 거듭제곱 계산
        temp = digit_count - 1;
        while temp > 0 {
            pow10 = pow10 * 10;
            temp = temp - 1;
        }

        // 각 자리수 변환
        let idx = 0;
        temp = n;
        for idx = 0; idx < digit_count; idx = idx + 1 {
            let digit = (temp / pow10) % 10;
            if digit == 0 {
                digits = digits + "0";
            } else if digit == 1 {
                digits = digits + "1";
            } else if digit == 2 {
                digits = digits + "2";
            } else if digit == 3 {
                digits = digits + "3";
            } else if digit == 4 {
                digits = digits + "4";
            } else if digit == 5 {
                digits = digits + "5";
            } else if digit == 6 {
                digits = digits + "6";
            } else if digit == 7 {
                digits = digits + "7";
            } else if digit == 8 {
                digits = digits + "8";
            } else if digit == 9 {
                digits = digits + "9";
            }
            pow10 = pow10 / 10;
        }

        return digits;
    }
}

