//   - 헬퍼 함수
// ============================================================================

module query_runner {
    // === 에러 코드 (170-172) ===
    const QR_OK:        i32 = 0;
    const QR_ERR_PLAN:  i32 = 170;
    const QR_ERR_EXEC:  i32 = 171;
    const QR_ERR_PARSE: i32 = 172;

    // === 제한값 ===
    const MAX_RESULT_ROWS: i32 = 1024;

    // === 데이터 구조체 ===

    // 파이프라인 통계 및 상태
    struct PipelineStats {
        parse_ok:    bool;
        plan_type:   i32;
        op_count:    i32;
        result_rows: i32;
        error_code:  i32;
    }

    // 통합 쿼리 실행 엔진
