// ============================================================================
// FreeLang Query Runner 모듈 - 통합 쿼리 실행 파이프라인
// ============================================================================
// 목표: planner→physical_plan→executor→result_set 통합 파이프라인 facade
// 원리:
//   1. QueryRunner: 모든 실행 단계를 통합 관리
//   2. query_runner_execute: SQL 문자열 → 파싱 → 계획 → 실행 → 결과
//   3. 에러 처리: 각 단계별 에러 코드 전파 (QR_ERR_*)
// 구조:
//   - 상수 정의 (에러 코드, 제한값)
//   - PipelineStats, QueryRunner 구조체
//   - 초기화 및 실행 함수 (8개 공개 API)
//   - 헬퍼 함수
// ============================================================================

module query_runner {
    // === 에러 코드 (170-172) ===
    const QR_OK:        i32 = 0;
    const QR_ERR_PLAN:  i32 = 170;
    const QR_ERR_EXEC:  i32 = 171;
    const QR_ERR_PARSE: i32 = 172;

    // === 제한값 ===
    const MAX_RESULT_ROWS: i32 = 1024;

    // === 데이터 구조체 ===

    // 파이프라인 통계 및 상태
    struct PipelineStats {
        parse_ok:    bool;
        plan_type:   i32;
        op_count:    i32;
        result_rows: i32;
        error_code:  i32;
    }

    // 통합 쿼리 실행 엔진
    struct QueryRunner {
        pq:        query_parser.ParsedQuery;
        exec_plan: planner.ExecPlan;
        phys_plan: physical_plan.PhysicalPlan;
        ex:        executor.Executor;
        result:    result_set.ResultSet;
        stats:     PipelineStats;
        has_error: bool;
        error_code: i32;
        // === Phase 12: 옵티마이저 추가 ===
        optimizer:     query_optimizer.OptimizerContext;
        use_optimizer: bool;
    }

    // === 초기화 함수 ===

    // 새로운 QueryRunner 생성 및 초기화
    func query_runner_new() -> QueryRunner {
        let qr = QueryRunner{
            pq:        query_parser.ParsedQuery{
                table_name:    "",
                where_col_idx: -1,
                where_op:      0,
                where_val_int: 0,
                order_col_idx: -1,
                order_desc:    false,
                limit_count:   -1,
                has_error:     false,
                error_code:    0,
            },
            exec_plan: planner.ExecPlan{
                plan_type:  0,
                index_col:  -1,
                est_rows:   0,
                cost:       0,
                error_code: 0,
            },
            phys_plan: physical_plan.physical_plan_new(),
            ex:        executor.executor_new(),
            result:    result_set.result_set_new(16),
            stats:     PipelineStats{
                parse_ok:    false,
                plan_type:   0,
                op_count:    0,
                result_rows: 0,
                error_code:  0,
            },
            has_error: false,
            error_code: QR_OK,
            // === Phase 12 초기화 ===
            optimizer:     query_optimizer.optimizer_new(),
            use_optimizer: false,
        };
        return qr;
    }

    // === 메인 실행 함수 (핵심) ===

    // 통합 쿼리 실행 파이프라인
    // SQL 문자열 → 파싱 → 계획 → 물리 계획 → 실행 → 결과
    func query_runner_execute(qr: *QueryRunner, t: schema.Table, sql: string) -> i32 {
        // 1단계: SQL 파싱
        qr.pq = query_parser.parse_query(sql, t);
        if qr.pq.has_error {
            qr.has_error = true;
            qr.error_code = QR_ERR_PARSE;
            qr.stats.error_code = QR_ERR_PARSE;
            qr.stats.parse_ok = false;
            return QR_ERR_PARSE;
        }
        qr.stats.parse_ok = true;

        // 2단계: 테이블 통계 수집 (병목 2: Phase 12 캐싱 추가)
        let stats = planner.TableStats{
            row_count:    0,
            col_count:    0,
            col_min:      make([i64], 16),
            col_max:      make([i64], 16),
            col_null_cnt: make([i32], 16),
            col_type:     make([i32], 16),
        };
        if qr.use_optimizer {
            // StatsCache 사용 (O(1) 캐시 히트 시)
            stats = stats_cache.stats_cache_get(&qr.optimizer.stats_cache, t);
        } else {
            // 기존 방식 (항상 O(n))
            stats = planner.stats_build(t);
        }

        // 3단계: 쿼리 구조 생성 및 비용 기반 실행 계획 수립
        let q = query.query_table(t);

        // WHERE 절 추가 (파서에서 추출된 정보 사용)
        if qr.pq.where_col_idx >= 0 {
            let col_type = t.schema.col_defs[qr.pq.where_col_idx].col_type;

            // INT 컬럼 조건 추가
            if col_type == schema.COL_TYPE_INT {
                let op_val = qr.pq.where_op;
                // 파서의 연산자 코드를 query.fl의 코드로 매핑
                let mapped_op = op_val;  // 같은 코드 체계 사용
                q.where_int(qr.pq.where_col_idx, mapped_op, qr.pq.where_val_int);
            }
        }

        // ORDER BY 설정
        if qr.pq.order_col_idx >= 0 {
            q.order_by_col(qr.pq.order_col_idx, !qr.pq.order_desc);
        }

        // LIMIT 설정
        if qr.pq.limit_count > 0 {
            q.limit(qr.pq.limit_count);
        }

        // 4단계: 비용 기반 실행 계획 생성
        qr.exec_plan = planner.plan_query(q, stats, false, false);
        if qr.exec_plan.error_code != planner.PLAN_OK {
            qr.has_error = true;
            qr.error_code = QR_ERR_PLAN;
            qr.stats.error_code = QR_ERR_PLAN;
            return QR_ERR_PLAN;
        }
        qr.stats.plan_type = qr.exec_plan.plan_type;

        // 5단계: 논리 계획을 물리 계획으로 변환
        let phys_err = 0;
        (qr.phys_plan, phys_err) = physical_plan.physical_plan_from_logical(qr.exec_plan);
        if phys_err != physical_plan.PHYS_OK {
            qr.has_error = true;
            qr.error_code = QR_ERR_PLAN;
            qr.stats.error_code = QR_ERR_PLAN;
            return QR_ERR_PLAN;
        }
        qr.stats.op_count = qr.phys_plan.op_count;

        // 6단계: Executor 생성 및 초기화
        qr.ex = executor.executor_new();
        let init_err = executor.executor_init(&qr.ex, qr.phys_plan, t);
        if init_err != executor.EXEC_OK {
            qr.has_error = true;
            qr.error_code = QR_ERR_EXEC;
            qr.stats.error_code = QR_ERR_EXEC;
            return QR_ERR_EXEC;
        }

        // 7단계: 물리 계획 실행
        let exec_err = executor.executor_execute(&qr.ex, t);
        if exec_err != executor.EXEC_OK {
            qr.has_error = true;
            qr.error_code = QR_ERR_EXEC;
            qr.stats.error_code = QR_ERR_EXEC;
            return QR_ERR_EXEC;
        }

        // 8단계: 결과 집합 추출 및 행 수 기록
        qr.result = executor.executor_get_result(&qr.ex);
        qr.stats.result_rows = result_set.result_set_get_row_count(&qr.result);

        qr.has_error = false;
        qr.error_code = QR_OK;
        qr.stats.error_code = QR_OK;

        return QR_OK;
    }

    // === 결과 조회 함수 ===

    // 쿼리 결과 집합 반환
    func query_runner_get_result(qr: *QueryRunner) -> result_set.ResultSet {
        return qr.result;
    }

    // 결과 행 수 반환
    func query_runner_get_row_count(qr: *QueryRunner) -> i32 {
        return qr.stats.result_rows;
    }

    // 결과를 문자열로 변환
    func query_runner_result_to_string(qr: *QueryRunner) -> string {
        return result_set.result_set_to_string(&qr.result);
    }

    // === 메타데이터 함수 ===

    // 선택된 실행 계획 타입 반환
    func query_runner_get_plan_type(qr: *QueryRunner) -> i32 {
        return qr.stats.plan_type;
    }

    // === 관리 함수 ===

    // QueryRunner 리셋 (재사용 가능하게 초기화)
    func query_runner_reset(qr: *QueryRunner) -> i32 {
        // 모든 필드 초기화
        qr.pq = query_parser.ParsedQuery{
            table_name:    "",
            where_col_idx: -1,
            where_op:      0,
            where_val_int: 0,
            order_col_idx: -1,
            order_desc:    false,
            limit_count:   -1,
            has_error:     false,
            error_code:    0,
        };

        qr.exec_plan = planner.ExecPlan{
            plan_type:  0,
            index_col:  -1,
            est_rows:   0,
            cost:       0,
            error_code: 0,
        };

        qr.phys_plan = physical_plan.physical_plan_new();
        qr.ex = executor.executor_new();
        qr.result = result_set.result_set_new(16);

        qr.stats = PipelineStats{
            parse_ok:    false,
