                limit_count:   -1,
                has_error:     false,
                error_code:    0,
            },
            exec_plan: planner.ExecPlan{
                plan_type:  0,
                index_col:  -1,
                est_rows:   0,
                cost:       0,
                error_code: 0,
            },
            phys_plan: physical_plan.physical_plan_new(),
            ex:        executor.executor_new(),
            result:    result_set.result_set_new(16),
            stats:     PipelineStats{
                parse_ok:    false,
                plan_type:   0,
                op_count:    0,
                result_rows: 0,
                error_code:  0,
            },
            has_error: false,
            error_code: QR_OK,
            // === Phase 12 초기화 ===
            optimizer:     query_optimizer.optimizer_new(),
            use_optimizer: false,
        };
        return qr;
    }

    // === 메인 실행 함수 (핵심) ===

    // 통합 쿼리 실행 파이프라인
    // SQL 문자열 → 파싱 → 계획 → 물리 계획 → 실행 → 결과
    func query_runner_execute(qr: *QueryRunner, t: schema.Table, sql: string) -> i32 {
        // 1단계: SQL 파싱
        qr.pq = query_parser.parse_query(sql, t);
        if qr.pq.has_error {
            qr.has_error = true;
            qr.error_code = QR_ERR_PARSE;
            qr.stats.error_code = QR_ERR_PARSE;
            qr.stats.parse_ok = false;
            return QR_ERR_PARSE;
        }
        qr.stats.parse_ok = true;

        // 2단계: 테이블 통계 수집 (병목 2: Phase 12 캐싱 추가)
        let stats = planner.TableStats{
            row_count:    0,
            col_count:    0,
            col_min:      make([i64], 16),
            col_max:      make([i64], 16),
            col_null_cnt: make([i32], 16),
            col_type:     make([i32], 16),
        };
        if qr.use_optimizer {
            // StatsCache 사용 (O(1) 캐시 히트 시)
            stats = stats_cache.stats_cache_get(&qr.optimizer.stats_cache, t);
        } else {
            // 기존 방식 (항상 O(n))
            stats = planner.stats_build(t);
        }

