        }

        // 7단계: 물리 계획 실행
        let exec_err = executor.executor_execute(&qr.ex, t);
        if exec_err != executor.EXEC_OK {
            qr.has_error = true;
            qr.error_code = QR_ERR_EXEC;
            qr.stats.error_code = QR_ERR_EXEC;
            return QR_ERR_EXEC;
        }

        // 8단계: 결과 집합 추출 및 행 수 기록
        qr.result = executor.executor_get_result(&qr.ex);
        qr.stats.result_rows = result_set.result_set_get_row_count(&qr.result);

        qr.has_error = false;
        qr.error_code = QR_OK;
        qr.stats.error_code = QR_OK;

        return QR_OK;
    }

    // === 결과 조회 함수 ===

    // 쿼리 결과 집합 반환
    func query_runner_get_result(qr: *QueryRunner) -> result_set.ResultSet {
        return qr.result;
    }

    // 결과 행 수 반환
    func query_runner_get_row_count(qr: *QueryRunner) -> i32 {
        return qr.stats.result_rows;
    }

    // 결과를 문자열로 변환
    func query_runner_result_to_string(qr: *QueryRunner) -> string {
        return result_set.result_set_to_string(&qr.result);
    }

    // === 메타데이터 함수 ===

    // 선택된 실행 계획 타입 반환
    func query_runner_get_plan_type(qr: *QueryRunner) -> i32 {
        return qr.stats.plan_type;
    }

    // === 관리 함수 ===

    // QueryRunner 리셋 (재사용 가능하게 초기화)
    func query_runner_reset(qr: *QueryRunner) -> i32 {
        // 모든 필드 초기화
        qr.pq = query_parser.ParsedQuery{
            table_name:    "",
            where_col_idx: -1,
            where_op:      0,
            where_val_int: 0,
            order_col_idx: -1,
            order_desc:    false,
            limit_count:   -1,
            has_error:     false,
            error_code:    0,
        };

        qr.exec_plan = planner.ExecPlan{
            plan_type:  0,
            index_col:  -1,
            est_rows:   0,
            cost:       0,
            error_code: 0,
        };

        qr.phys_plan = physical_plan.physical_plan_new();
        qr.ex = executor.executor_new();
        qr.result = result_set.result_set_new(16);

        qr.stats = PipelineStats{
            parse_ok:    false,
            plan_type:   0,
            op_count:    0,
            result_rows: 0,
            error_code:  0,
        };

        qr.has_error = false;
        qr.error_code = QR_OK;

        // Phase 12: optimizer는 상태 유지 (통계 캐시 유지)
        // use_optimizer 플래그는 유지

        return QR_OK;
    }

    // === 디버그 함수 ===

    // QueryRunner 상태 문자열 표현
    func query_runner_stats(qr: *QueryRunner) -> string {
        let result = "QueryRunner {parse_ok: ";

        if qr.stats.parse_ok {
            result = result + "true";
        } else {
            result = result + "false";
        }

        result = result + ", plan_type: ";
        result = result + int_to_string(qr.stats.plan_type);

        result = result + ", op_count: ";
        result = result + int_to_string(qr.stats.op_count);

        result = result + ", result_rows: ";
        result = result + int_to_string(qr.stats.result_rows);

        result = result + ", error: ";
        result = result + int_to_string(qr.stats.error_code);

        result = result + "}";

        return result;
    }

    // === 헬퍼 함수 ===

    // 정수를 문자열로 변환
    @inline
    func int_to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }
        if n < 0 {
            return "-" + int_to_string(-n);
        }

        let digits = "";
        let temp = n;
        let digit_count = 0;
        let pow10 = 1;

        // 자리수 계산
        while temp > 0 {
            digit_count = digit_count + 1;
            temp = temp / 10;
        }

        // 10의 거듭제곱 계산
        temp = digit_count - 1;
        while temp > 0 {
            pow10 = pow10 * 10;
            temp = temp - 1;
        }

        // 각 자리수 변환
        let idx = 0;
        temp = n;
        for idx = 0; idx < digit_count; idx = idx + 1 {
            let digit = (temp / pow10) % 10;
            if digit == 0 {
                digits = digits + "0";
            } else if digit == 1 {
                digits = digits + "1";
            } else if digit == 2 {
                digits = digits + "2";
            } else if digit == 3 {
                digits = digits + "3";
            } else if digit == 4 {
                digits = digits + "4";
            } else if digit == 5 {
                digits = digits + "5";
            } else if digit == 6 {
                digits = digits + "6";
            } else if digit == 7 {
                digits = digits + "7";
            } else if digit == 8 {
                digits = digits + "8";
            } else if digit == 9 {
                digits = digits + "9";
            }
            pow10 = pow10 / 10;
        }

        return digits;
    }
}

