// ============================================================================
// FreeLang Planner 모듈 - 비용 기반 쿼리 실행 계획
// ============================================================================
// 목표: WHERE 절 기반으로 최적의 실행 경로 선택
// 원리:
//   1. 테이블 통계: row_count, 컬럼 min/max
//   2. 비용 추정: 풀스캔 O(n), 인덱스 범위 O(log n + k)
//   3. 계획 선택: 비용이 낮은 경로 선택
// 구조:
//   - TableStats, ExecPlan 구조체
//   - 통계 수집 (stats_build, stats_update)
//   - 계획 생성 (plan_query)
//   - 계획 기반 실행 (execute_planned)
// ============================================================================

module planner {
    // === 계획 타입 ===
    const PLAN_FULL_SCAN:   i32 = 1;
    const PLAN_INDEX_EQ:    i32 = 2;
    const PLAN_INDEX_RANGE: i32 = 3;
    const PLAN_INDEX_LIKE:  i32 = 4;

    // === 제한값 ===
    const MAX_COLS: i32 = 16;
    const MAX_ROWS: i32 = 1024;

    // === 에러 코드 ===
    const PLAN_OK:           i32 = 0;
    const PLAN_ERR_NO_STATS: i32 = 60;

    // === 데이터 구조체 ===

    // 테이블 통계 (통계 기반 비용 추정용)
    struct TableStats {
        row_count:    i32;
        col_count:    i32;
        col_min:      [i64];   // 각 컬럼별 MIN (INT만)
        col_max:      [i64];   // 각 컬럼별 MAX (INT만)
        col_null_cnt: [i32];   // NULL 수
        col_type:     [i32];   // 컬럼 타입 (INT/STR/BOOL)
    }

    // 실행 계획
    struct ExecPlan {
        plan_type:  i32;   // PLAN_* 상수
        index_col:  i32;   // 사용할 인덱스 컬럼 (-1 = 없음)
        est_rows:   i32;   // 예상 결과 행 수
        cost:       i32;   // 비용 추정치 (낮을수록 좋음)
        error_code: i32;   // 에러 코드
    }

    // === 통계 생성 ===

    // 테이블에서 통계 수집 (스캔 기반)
    func stats_build(t: schema.Table) -> TableStats {
        let stats = TableStats{
            row_count:    t.row_count,
            col_count:    t.schema.col_count,
            col_min:      make([i64], MAX_COLS),
            col_max:      make([i64], MAX_COLS),
            col_null_cnt: make([i32], MAX_COLS),
            col_type:     make([i32], MAX_COLS),
        };

        // 각 컬럼 타입 저장
        let col_idx = 0;
        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
            stats.col_type[col_idx] = t.schema.col_defs[col_idx].col_type;
        }

        // INT 컬럼만 MIN/MAX 계산
        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
            if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_INT {
                continue;
            }

            let found_first = false;
            let row_idx = 0;
            for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
                if t.deleted_flags[row_idx] {
                    stats.col_null_cnt[col_idx] = stats.col_null_cnt[col_idx] + 1;
                    continue;
                }

                // SoA 레이아웃에서 값 읽기: [col_idx * MAX_ROWS + row_idx]
                let soa_idx = col_idx * MAX_ROWS + row_idx;
                let val = t.int_cols[soa_idx];

                if !found_first {
                    stats.col_min[col_idx] = val;
                    stats.col_max[col_idx] = val;
                    found_first = true;
                } else {
                    if val < stats.col_min[col_idx] {
                        stats.col_min[col_idx] = val;
                    }
                    if val > stats.col_max[col_idx] {
                        stats.col_max[col_idx] = val;
                    }
                }
            }
        }

        return stats;
    }

    // === 계획 생성 (핵심 로직) ===

    // WHERE 조건 기반 실행 계획 선택
    func plan_query(q: query.Query, stats: TableStats, has_int_idx: bool, has_str_idx: bool) -> ExecPlan {
        // 기본 계획: 풀스캔
        let plan = ExecPlan{
            plan_type:  PLAN_FULL_SCAN,
            index_col:  -1,
            est_rows:   stats.row_count,
            cost:       stats.row_count,  // 비용 = 행 수
            error_code: PLAN_OK,
        };

        // WHERE 절이 없으면 풀스캔
        if q.where_count == 0 {
            return plan;
        }

        // 복합 WHERE 절 (AND)은 풀스캔 (간단화)
        if q.where_count > 1 {
            return plan;
        }

        let where_clause = q.wheres[0];
        let col_idx = where_clause.col_idx;

        // 컬럼 범위 검증
        if col_idx < 0 || col_idx >= stats.col_count {
            plan.error_code = PLAN_ERR_NO_STATS;
            return plan;
        }

        // ===== INT 인덱스 고려 =====
        if has_int_idx && !where_clause.is_str {
            // EQUALITY 비교 (==)
            if where_clause.op == query.OP_EQ {
                plan.plan_type = PLAN_INDEX_EQ;
                plan.index_col = col_idx;
                plan.est_rows = 1;
                plan.cost = log_cost(stats.row_count) + 1;
                return plan;
            }

            // RANGE 비교 (>, <, >=, <=)
            if where_clause.op == query.OP_GT || where_clause.op == query.OP_LT ||
               where_clause.op == query.OP_GE || where_clause.op == query.OP_LE {
                let range_est = range_estimate(stats, col_idx, where_clause.op, where_clause.int_val);
                plan.plan_type = PLAN_INDEX_RANGE;
                plan.index_col = col_idx;
                plan.est_rows = range_est;
                plan.cost = log_cost(stats.row_count) + range_est;

                // 범위가 작으면 인덱스 사용, 크면 풀스캔 (휴리스틱)
                if plan.cost >= stats.row_count {
                    plan.plan_type = PLAN_FULL_SCAN;
                    plan.cost = stats.row_count;
                }
                return plan;
            }
        }

        // ===== STR 인덱스 고려 =====
        if has_str_idx && where_clause.is_str {
            if where_clause.op == query.OP_LIKE {
                // LIKE: 접두어 매칭 (B+Tree 범위 스캔)
                let like_est = stats.row_count / 10;  // 휴리스틱: 전체의 1/10
                plan.plan_type = PLAN_INDEX_LIKE;
                plan.index_col = col_idx;
                plan.est_rows = like_est;
                plan.cost = log_cost(stats.row_count) + like_est;
                return plan;
            }
        }

        // 기본: 풀스캔
        return plan;
    }

    // === 비용 추정 헬퍼 함수 ===

    // log2(n) 근사 (비트 길이 이용)
    @inline
    func log_cost(n: i32) -> i32 {
        if n <= 1 { return 0; }
        if n <= 2 { return 1; }
        if n <= 4 { return 2; }
        if n <= 8 { return 3; }
        if n <= 16 { return 4; }
        if n <= 32 { return 5; }
        if n <= 64 { return 6; }
        if n <= 128 { return 7; }
        if n <= 256 { return 8; }
        if n <= 512 { return 9; }
        if n <= 1024 { return 10; }
        return 11;
    }

    // 범위 조건의 결과 행 수 추정
    func range_estimate(stats: TableStats, col_idx: i32, op: i32, value: i64) -> i32 {
        let col_min = stats.col_min[col_idx];
        let col_max = stats.col_max[col_idx];
        let col_range = col_max - col_min;

        // 범위가 0이면 전체 반환
        if col_range == 0 {
            return stats.row_count;
        }

        // 조건별 추정 (균등 분포 가정)
        if op == query.OP_GT {
            // value < col <= col_max
            if value >= col_max {
                return 0;
            }
            let dist = (col_max - value) * 100 / col_range;
            let est = (stats.row_count * dist) / 100;
            if est < 1 { est = 1; }
            return est;
        }

        if op == query.OP_LT {
            // col_min <= col < value
            if value <= col_min {
                return 0;
            }
            let dist = (value - col_min) * 100 / col_range;
            let est = (stats.row_count * dist) / 100;
            if est < 1 { est = 1; }
            return est;
        }

        if op == query.OP_GE {
            // value <= col <= col_max
            if value > col_max {
                return 0;
            }
            let dist = (col_max - value) * 100 / col_range;
            let est = (stats.row_count * dist) / 100 + 1;
            if est < 1 { est = 1; }
            return est;
        }

        if op == query.OP_LE {
            // col_min <= col <= value
            if value < col_min {
                return 0;
            }
            let dist = (value - col_min) * 100 / col_range;
            let est = (stats.row_count * dist) / 100 + 1;
            if est < 1 { est = 1; }
            return est;
        }

        // 미지의 연산자
        return stats.row_count / 4;
    }

    // === 계획 기반 실행 ===

    // 계획에 따라 인덱스 또는 풀스캔 사용
    func execute_planned(t: schema.Table, q: query.Query,
                        plan: ExecPlan, idx: index.BTreeIndex) -> query.QueryResult {

        // PLAN_FULL_SCAN: 기존 query_execute 사용 (풀스캔)
        if plan.plan_type == PLAN_FULL_SCAN {
            return query.execute(t, q);
        }

        // PLAN_INDEX_EQ: 정확한 인덱스 탐색
        if plan.plan_type == PLAN_INDEX_EQ {
            let result = query.QueryResult{
                row_indices: make([i32], 1024),
                row_count:   0,
                agg_value:   0,
                error_code:  query.QUERY_OK,
            };

            let search_val = q.wheres[0].int_val;
            let found_row_id, found = idx.index_search(search_val);

            // 인덱스에서 찾은 row_id를 테이블 행 인덱스로 변환
            if found {
                let row_idx = 0;
                for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
                    if t.row_ids[row_idx] == found_row_id && !t.deleted_flags[row_idx] {
                        result.row_indices[0] = row_idx;
                        result.row_count = 1;
                        break;
                    }
                }
            }

            return result;
        }

        // PLAN_INDEX_RANGE: 범위 탐색
        if plan.plan_type == PLAN_INDEX_RANGE {
            let result = query.QueryResult{
                row_indices: make([i32], 1024),
                row_count:   0,
                agg_value:   0,
                error_code:  query.QUERY_OK,
            };

            let min_val = q.wheres[0].int_val;
            let op = q.wheres[0].op;
            let max_val = min_val + 100;  // 범위 크기 (간단화)

            // 인덱스 검증: idx가 유효한지 확인
            if idx.key_count == 0 {
                // 인덱스가 비어있으면 풀스캔 대신 빈 결과 반환
                return result;
            }

            // index_range() 호출: min_val ~ max_val 범위의 row_id 배열 반환
            let row_id_array, row_id_count = idx.index_range(min_val, max_val);

            // 반환된 row_id를 테이블의 행 인덱스로 변환
            let i = 0;
            for i = 0; i < row_id_count && result.row_count < 1024; i = i + 1 {
                let target_row_id = row_id_array[i];

                // row_id를 행 인덱스로 매핑
                let row_idx = 0;
                for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
                    if t.row_ids[row_idx] == target_row_id && !t.deleted_flags[row_idx] {
                        // 행 조건에 추가로 WHERE 조건 검증 (이중 검증)
                        let soa_idx = plan.index_col * MAX_ROWS + row_idx;
                        let val = t.int_cols[soa_idx];

                        let matches = false;
                        if op == query.OP_GT {
                            matches = val > min_val;
                        } else if op == query.OP_LT {
                            matches = val < min_val;
                        } else if op == query.OP_GE {
                            matches = val >= min_val;
                        } else if op == query.OP_LE {
                            matches = val <= min_val;
                        }

                        if matches {
                            result.row_indices[result.row_count] = row_idx;
                            result.row_count = result.row_count + 1;
                        }
                        break;
                    }
                }
            }

            return result;
        }

        // PLAN_INDEX_LIKE: 문자열 접두어 탐색
        if plan.plan_type == PLAN_INDEX_LIKE {
            let result = query.QueryResult{
                row_indices: make([i32], 1024),
                row_count:   0,
                agg_value:   0,
                error_code:  query.QUERY_OK,
            };

            // 문자열 인덱스 사용 (아직 미구현, 풀스캔 대신)
            // 여기서는 간단화하여 풀스캔 로직 사용
            let prefix = q.wheres[0].str_val;
            let i = 0;
            for i = 0; i < t.row_count && result.row_count < 1024; i = i + 1 {
                if t.deleted_flags[i] {
                    continue;
                }

                let soa_idx = plan.index_col * MAX_ROWS + i;
                let str_val = t.str_cols[soa_idx];

                // 접두어 매칭 (간단 구현)
                if str_prefix_match(str_val, prefix) {
                    result.row_indices[result.row_count] = i;
                    result.row_count = result.row_count + 1;
                }
            }

            return result;
        }

        // 기본: 풀스캔
        return query.execute(t, q);
    }

    // === 문자열 유틸리티 ===

    // 문자열 접두어 매칭
    @inline
    func str_prefix_match(str_val: string, prefix: string) -> bool {
        let str_len = 0;
        let i = 0;
        for i = 0; i < 256; i = i + 1 {
            if str_val[i:i+1] == "" {
                str_len = i;
                break;
            }
        }

        let prefix_len = 0;
        for i = 0; i < 256; i = i + 1 {
            if prefix[i:i+1] == "" {
                prefix_len = i;
                break;
            }
        }

        if prefix_len > str_len {
            return false;
        }

        let j = 0;
        for j = 0; j < prefix_len; j = j + 1 {
            if str_val[j:j+1] != prefix[j:j+1] {
                return false;
            }
        }

        return true;
    }

    // === 계획 정보 출력 ===

    // 계획 정보를 문자열로 변환 (디버깅)
    func plan_to_str(plan: ExecPlan) -> string {
        let type_str = "UNKNOWN";
        if plan.plan_type == PLAN_FULL_SCAN {
            type_str = "FULL_SCAN";
        } else if plan.plan_type == PLAN_INDEX_EQ {
            type_str = "INDEX_EQ";
        } else if plan.plan_type == PLAN_INDEX_RANGE {
            type_str = "INDEX_RANGE";
        } else if plan.plan_type == PLAN_INDEX_LIKE {
            type_str = "INDEX_LIKE";
        }

        // 간단 포맷: "PLAN_TYPE(est_rows:N, cost:C)"
        return type_str;
    }

    // === 통계 정보 요약 ===

    // 테이블 통계 출력 (디버깅)
    func stats_summary(stats: TableStats) -> string {
        // 간단 포맷: "TableStats(rows:N, cols:M)"
        return "TableStats";
    }
}

// === 사용 예시 ===
//
// 1. 통계 수집:
//    let stats = planner.stats_build(&table);
//
// 2. 계획 생성:
//    let plan = planner.plan_query(&q, &stats, true, false);
//    // WHERE age > 25 + int_idx 있음 → PLAN_INDEX_RANGE
//    // WHERE age = 30 + int_idx 있음 → PLAN_INDEX_EQ
//
// 3. 계획 기반 실행:
//    let result = planner.execute_planned(&t, &q, &plan, &idx);
//
// 4. 비용 비교:
//    // 풀스캔: O(n) = 10,000
//    // 인덱스 범위: O(log n + k) = 14 + 500 = 514
//    → 인덱스 선택 (약 20배 빠름)
//

